<?php
require __DIR__ . '/_auth.php';
$id = trim($_GET['id'] ?? '');
$category = $_GET['category'] ?? ($_POST['category'] ?? 'kenyan');
$allowed = ['safari', 'kenyan', 'international', 'package'];
if (!in_array($category, $allowed, true)) $category = 'kenyan';
$pdo->exec("CREATE TABLE IF NOT EXISTS trips (id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, category VARCHAR(32) NOT NULL DEFAULT 'kenyan', price DECIMAL(10,2) NOT NULL DEFAULT 0.00, image VARCHAR(255), description TEXT, detail_link VARCHAR(255))");
foreach (["ALTER TABLE trips ADD COLUMN IF NOT EXISTS category VARCHAR(32) NOT NULL DEFAULT 'kenyan'", "ALTER TABLE trips ADD COLUMN IF NOT EXISTS image VARCHAR(255) NULL", "ALTER TABLE trips ADD COLUMN IF NOT EXISTS detail_link VARCHAR(255) NULL"] as $migration) { try { $pdo->exec($migration); } catch (Exception $e) {} }
$trip = null;
if ($id) { $stmt = $pdo->prepare('SELECT * FROM trips WHERE id = ?'); $stmt->execute([$id]); $trip = $stmt->fetch(); if ($trip) $category = $trip['category']; }
if (!isset($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals($_SESSION['csrf'], $_POST['csrf'] ?? '')) {
    $tripId = trim($_POST['id'] ?? ''); $title = trim($_POST['title'] ?? ''); $price = (float) ($_POST['price'] ?? 0); $description = trim($_POST['description'] ?? ''); $detailLink = trim($_POST['detail_link'] ?? ''); $image = $trip['image'] ?? null;
    if (!in_array($_POST['category'] ?? '', $allowed, true)) $error = 'Invalid category.'; else $category = $_POST['category'];
    if (!$tripId || !$title) $error = 'ID and title are required.';
    if (!$error && !empty($_FILES['image']['tmp_name'])) {
        $upload = $_FILES['image']; $mime = (new finfo(FILEINFO_MIME_TYPE))->file($upload['tmp_name']); $types = ['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif'];
        if ($upload['error'] !== UPLOAD_ERR_OK) $error = 'Image upload error.'; elseif ($upload['size'] > 2 * 1024 * 1024) $error = 'Image too large (max 2MB).'; elseif (!isset($types[$mime])) $error = 'Invalid image type (use JPG, PNG, or GIF).';
        else { $dir = __DIR__ . '/../assets/images/trips'; if (!is_dir($dir) && !mkdir($dir, 0755, true)) $error = 'Could not create trip image folder.'; else { $name = uniqid('trip_', true) . '.' . $types[$mime]; if (move_uploaded_file($upload['tmp_name'], $dir . '/' . $name)) $image = 'assets/images/trips/' . $name; else $error = 'Failed to move uploaded file.'; } }
    }
    if (!$error) { try { $stmt = $pdo->prepare('INSERT INTO trips (id,title,category,price,image,description,detail_link) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title), category=VALUES(category), price=VALUES(price), image=VALUES(image), description=VALUES(description), detail_link=VALUES(detail_link)'); $stmt->execute([$tripId, $title, $category, $price, $image, $description, $detailLink]); header('Location: ' . $category . '_trips.php'); exit; } catch (PDOException $e) { $error = 'Could not save trip. The ID may be invalid.'; } }
}
$labels = ['safari'=>'Safari', 'kenyan'=>'Kenyan', 'international'=>'International', 'package'=>'Package'];
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo $trip ? 'Edit' : 'Add'; ?> Trip — Admin</title><link rel="stylesheet" href="/assets/css/site.css"></head><body>
<nav class="site-nav"><div class="container nav-inner"><div class="brand"><img class="site-logo" src="/assets/images/TransparentTravelDen-Logo.png" alt="TraveL Den Adventures"><div><h1>Admin</h1></div></div><div style="margin-left:auto"><a href="index.php">Dashboard</a> | <a href="logout.php">Logout</a></div></div></nav>
<main class="container" style="max-width:800px;margin-top:20px"><p><a href="<?php echo htmlspecialchars($category) ?>_trips.php">&larr; <?php echo htmlspecialchars($labels[$category]); ?> trips</a></p><h2><?php echo $trip ? 'Edit' : 'Add'; ?> <?php echo htmlspecialchars($labels[$category]); ?> trip</h2><?php if ($error): ?><div class="card" style="background:#ffecec;color:#900;padding:12px"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><div class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['csrf']); ?>"><div class="form-row"><label>ID (slug)</label><input name="id" value="<?php echo htmlspecialchars($trip['id'] ?? ''); ?>" required></div><div class="form-row"><label>Category</label><select name="category"><?php foreach ($labels as $value => $label): ?><option value="<?php echo $value; ?>" <?php echo $category === $value ? 'selected' : ''; ?>><?php echo $label; ?></option><?php endforeach; ?></select></div><div class="form-row"><label>Title</label><input name="title" value="<?php echo htmlspecialchars($trip['title'] ?? ''); ?>" required></div><div class="form-row"><label>Price (KSh)</label><input name="price" type="number" step="0.01" value="<?php echo htmlspecialchars($trip['price'] ?? '0'); ?>"></div><div class="form-row"><label>Description</label><textarea name="description" rows="8"><?php echo htmlspecialchars($trip['description'] ?? ''); ?></textarea></div><div class="form-row"><label>Detail HTML page</label><input name="detail_link" placeholder="tripspages/trip_example.html" value="<?php echo htmlspecialchars($trip['detail_link'] ?? ''); ?>"></div><div class="form-row"><label>Image</label><input type="file" name="image" accept="image/jpeg,image/png,image/gif"></div><?php if (!empty($trip['image'])): ?><div class="form-row"><img src="../<?php echo htmlspecialchars($trip['image']); ?>" alt="Current trip image" style="max-width:220px;max-height:140px"></div><?php endif; ?><button class="primary">Save Trip</button></form></div></main></body></html>
